export function socialApplicationDestination(text:string, claimed='') {
  const contact=supportedContact(text.replace(/https?:\/\/[^\s<>()]+/gi,''),claimed);
  if (contact) return { kind:contact.includes('@') ? 'email' : 'phone',value:contact };
