    for (const match of block.matchAll(/(?:https?:\/\/|(?:www\.)?[a-z0-9.-]+\.(?:cl|com|org|net)\/)[^\s<>()]+/gi)) {
      try {
        const raw=match[0].replace(/[.,;]+$/,'');
        const url=new URL(/^https?:/i.test(raw) ? raw : 'https://'+raw);
